/// Tracks which warnings have already been displayed so that repeated,
/// model-specific metadata warnings are only surfaced once per model slug.
#[derive(Default)]
pub(super) struct WarningDisplayState {
    /// Model slugs for which the "model metadata not found" warning has
    /// already been shown.
    seen_model_metadata_slugs: HashSet<String>,
}

impl WarningDisplayState {
    /// Returns `true` if the given warning message should be added to the
    /// conversation history, `false` if it should be suppressed.
    ///
    /// Model metadata warnings are deduplicated per slug: the first occurrence
    /// for a given slug returns `true` and every subsequent occurrence for the
    /// same slug returns `false`. All other warnings always return `true`.
    pub(super) fn should_display(&mut self, message: &str) -> bool {
        match extract_model_metadata_slug(message) {
            Some(slug) => self.seen_model_metadata_slugs.insert(slug.to_string()),
            None => true,
        }
    }
}

/// If `message` matches the model metadata warning pattern
/// "Model metadata for `{slug}` not found. Defaulting to fallback metadata;
/// this can degrade performance and cause issues.", returns the extracted
/// `{slug}`. Otherwise returns `None`.
fn extract_model_metadata_slug(message: &str) -> Option<&str> {
    const PREFIX: &str = "Model metadata for `";
    const SUFFIX: &str = "` not found. Defaulting to fallback metadata; this can degrade performance and cause issues.";

    let rest = message.strip_prefix(PREFIX)?;
    rest.strip_suffix(SUFFIX)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn metadata_warning(slug: &str) -> String {
        format!(
            "Model metadata for `{slug}` not found. Defaulting to fallback metadata; this can degrade performance and cause issues."
        )
    }

    #[test]
    fn deduplicates_model_metadata_warnings_per_slug() {
        let mut state = WarningDisplayState::default();
        let warning = metadata_warning("unknown-model");

        assert!(state.should_display(&warning));
        assert!(!state.should_display(&warning));
        assert!(!state.should_display(&warning));

        // A different slug is displayed once.
        let other = metadata_warning("other-model");
        assert!(state.should_display(&other));
        assert!(!state.should_display(&other));
    }

    #[test]
    fn generic_warnings_always_display() {
        let mut state = WarningDisplayState::default();
        let warning = "Something else went wrong.";

        assert!(state.should_display(warning));
        assert!(state.should_display(warning));
        assert!(state.should_display(warning));
    }
}
